param([ValidateSet('x86','x64')][string]$Platform)
$ErrorActionPreference='Stop'
$root=Split-Path $PSScriptRoot -Parent
if(!$Platform) {
 foreach($arch in @('x86','x64')) {
  & powershell.exe -NoProfile -File $PSCommandPath -Platform $arch
  if($LASTEXITCODE -ne 0){throw "Custom ReShade build failed: $arch"}
 }
 exit 0
}
. "$root/.deps/dxvk-remix/bridge/build_common.ps1"
SetupVS -Platform $Platform -VcVarsVer '14.29'
$buildPlatform=if($Platform -eq 'x86'){'Win32'}else{'x64'}
$source="$root/.deps/reshade"
Push-Location $source
try {
 & msbuild.exe ReShade.vcxproj /m /nologo /v:minimal /p:Configuration=Release "/p:Platform=$buildPlatform" /p:PlatformToolset=v142 /p:WindowsTargetPlatformVersion=10.0 "/p:SolutionDir=$source\" "/flp:logfile=$root/work/reshade-$Platform-build.log;verbosity=normal"
 if($LASTEXITCODE -ne 0){throw "ReShade compilation failed: $Platform"}
} finally {Pop-Location}
